"""Cross-event binding harness for exact native-boundary evidence (4A.5B.11)."""
from __future__ import annotations

from dataclasses import dataclass

from workflow_kernel.effect_ledger_cross_relation_descriptors import (
    CROSS_EVENT_RELATION_DESCRIPTORS_V1,
    EXACT_CROSS_DESCRIPTOR_KEYS_V1,
)

EXACT_17_KEYS: frozenset[str] = frozenset(EXACT_CROSS_DESCRIPTOR_KEYS_V1)

@dataclass(frozen=True)
class CrossEventCaseContract:
    relation_id: str
    binding_id: str
    semantic_mutated_paths: tuple[str, ...]
    derived_bookkeeping_paths: tuple[str, ...]
    expected_code: str
    expected_message: str
    state_preservation: str
    accept_builder: str
    negative_mode: str
    destination_event_type: str
    comparison: str
    validator_function: str
    source_event: str
    destination_event: str
    expected_accept_status: str
    source_path: str
    destination_path: str
    boundary_marker: str | None = None
    pre_probe_full_event_parse: bool = False
    exec_mode: str = "primary"

@dataclass(frozen=True)
class BindingBoundaryExpectation:
    binding_id: str
    relation_id: str
    source_event: str
    source_path: str
    destination_event: str
    destination_path: str
    validator_function: str
    expected_code: str
    expected_message: str

@dataclass(frozen=True)
class HarnessSabotage:
    """Test-only sabotage object; must never exist in production code."""
    skip_good_append: bool = False
    skip_diff_guard: bool = False
    broaden_expected_message: str | None = None
    trace: list | None = None

    def _t(self, stage: str) -> None:
        if self.trace is not None:
            self.trace.append(stage)

